import{_ as i,l as n,o as e,c as o,v as t,p as s,x as r,d as c,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const k=JSON.parse('{"title":"轨道与扫描仪联机","description":"","frontmatter":{"title":"轨道与扫描仪联机","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/track-scanner-link.md","filePath":"litho/track-scanner-link.md","lastUpdated":1789023840000}'),E={name:"litho/track-scanner-link.md"};function p(_,a,B,u,m,P){const l=n("Mermaid");return e(),o("div",null,[a[1]||(a[1]=t('<h1 id="轨道与扫描仪联机" tabindex="-1">轨道与扫描仪联机 <a class="header-anchor" href="#轨道与扫描仪联机" aria-label="Permalink to &quot;轨道与扫描仪联机&quot;">​</a></h1><div class="epigraph"><p>涂胶–烘烤–显影在轨道，潜像在扫描仪。联机的是片、配方和时间，不是把两台机器写成一台。</p><footer>—— 对照 litho cluster（track + scanner）公开架构</footer></div><p><a href="/litho/hard-bake-uv-cure">上一课</a>停在显影后硬化。把整段工艺串起来，缺口是集群：哪一步在 track、哪一步在 scanner、片如何排队。主干 <a href="/litho/twinscan-dual-stage">Twinscan</a> 写过曝光产能；本课补轨道节拍与接口，不重写双工件台。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>扫描仪论场和剂量；轨道论模块占用：涂胶杯、热板、显影碗。节拍不匹配就堆片或饿曝光。PEB 延迟（曝光到 PEB 的时间）是化学放大胶的一等参数：酸在室温也会走，延迟散了 CD。把 PEB 延迟写成「剂量不稳」，会找错旋钮。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>集群调度：曝光后尽快进 PEB 模块，延迟分布要进 SPC。接口：晶圆 ID、配方号、slot 对齐，避免涂了 A 胶去曝 B 程序。环境：轨道与扫描仪的温湿度、氨污染（胺会淬灭酸）要当一个 mill 的化学环境，不是两家设备商各管一段。</p>',7)),(e(),s(h,null,{default:r(()=>[d(l,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20COAT%5B%22%E6%B6%82%E8%83%B6%E8%BD%AF%E7%83%A4%22%5D%20--%3E%20EXP%5B%22%E6%89%AB%E6%8F%8F%E4%BB%AA%E6%9B%9D%E5%85%89%22%5D%0A%20%20EXP%20--%3E%20PEB%5B%22PEB%22%5D%0A%20%20PEB%20--%3E%20DEV%5B%22%E6%98%BE%E5%BD%B1%E5%86%B2%E6%B4%97%22%5D%0A%20%20DEV%20--%3E%20HB%5B%22%E7%A1%AC%E7%83%A4%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p><span class="marginnote">离线曝光（track 与 scanner 分开）在研发机台常见，PEB 延迟靠人跑秒表。量产集群把延迟收成受控分布。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>CAR 的酸在曝光后即存在，扩散与淬灭从这一刻起算。调度方差直接变 CDU。胺类 airborne base 在排队时中和酸，表现为「等得越久越欠曝」。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>下一课热板均匀性：联机之后，仍可能是热板地图主导 CDU，而不是调度。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>集群把 PEB 延迟和环境化学收成受控量。</li><li>节拍匹配是产能，延迟匹配是 CD。</li><li>出处：litho cluster 通识；CAR 酸扩散课。</li></ul>',7))])}const f=i(E,[["render",p]]);export{k as __pageData,f as default};
